INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taryn Barker: Demon Hunter', 'Taryn Barker: Demon Hunter is an action-adventure game where you step into the shoes of Taryn, a skilled warrior with a dark past. You’ll fight your way through hordes of demonic creatures, solve puzzles, and explore dark, atmospheric environments reminiscent of classic survival horror and sword fighting games. Armed with a katana, twin blades, and a crossbow, you’ll face increasingly tough enemies as you uncover the mysteries behind the demonic invasion.' FROM games WHERE igdb_id = 344088 ON CONFLICT (game_id, language_code) DO NOTHING;
