INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadows Beneath the Badge: An Undercover Affair', 'Shadows Beneath the Badge: An Undercover Affair follows Detective Jake Dawson, undercover to expose crime boss Victor Delgado, and attorney Sarah Hamilton, investigating Delgado’s corrupt charity. Their lives collide at a gala, sparking a connection complicated by Jake’s secret identity. When Sarah unknowingly steps into Delgado’s operation, Jake risks his cover to save her. Despite feelings of betrayal, Sarah recognizes his sincerity. Together, they bring Delgado to justice, forging trust, mutual respect, and the beginnings of a heartfelt romance.' FROM games WHERE igdb_id = 337705 ON CONFLICT (game_id, language_code) DO NOTHING;
