INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-jumping-bird', 342155, '2025-04-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r6j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3kx6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Jumping Bird', 'The Jumping Bird is an exciting endless jumping game where you play as a the bird. Your goal is to ascend as high as possible, navigating through colorful obstacles. Each obstacle matches a specific color, and your bird can only pass through if it matches the obstacle''s hue. Collect items to change your bird''s color and continue your ascent. Test your reflexes and see how far you can go in this challenging and colorful adventure!' FROM games WHERE igdb_id = 342155 ON CONFLICT (game_id, language_code) DO NOTHING;
