INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laundromat Manager Simulator', 'Step into the world of Laundromat Manager Simulator—where your entrepreneurial skills and creative flair combine to transform a modest laundromat into a bustling business empire! Manage every detail, from upgrading state-of-the-art equipment to designing a standout interior, as you attract loyal customers and outshine the competition. Whether you’re a savvy strategist or a creative decorator, this is your chance to build the ultimate neighborhood laundry hub. Success is just a spin cycle away, are you ready to take it?' FROM games WHERE igdb_id = 330929 ON CONFLICT (game_id, language_code) DO NOTHING;
