INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Suun', 'Dr. Suun is a thrilling horror experience that combines intense chases with mind-bending puzzles. Players step into the shoes of James, a man drawn into the mystery of an abandoned hospital with a haunting past. As he uncovers its secrets, the lines between reality and nightmare begin to blur.' FROM games WHERE igdb_id = 339701 ON CONFLICT (game_id, language_code) DO NOTHING;
