INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simon the Sorcerer: Origins - Digital Deluxe Edition', 'Simon the Sorcerer: Origins serves as an official prequel to the cult classic series, revealing the protagonist''s backstory thirty years after his original debut. Players guide Simon through a magical world filled with wizards and creatures as he solves puzzles, experiments with alchemical devices, and learns powerful spells to uncover the prophecy about his origins. The game combines classic point-and-click mechanics with modern features, presenting hand-drawn graphics and voice acting by Chris Barrie. Players encounter various puzzles requiring item combinations and logical thinking while interacting with eccentric characters throughout the adventure. The Digital Deluxe Edition includes a digital artbook showcasing the game''s comic-style artwork and an official soundtrack featuring over 50 minutes of music composed by Mason Fisher.' FROM games WHERE igdb_id = 365551 ON CONFLICT (game_id, language_code) DO NOTHING;
