INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pudding Frog', 'Dive into Pudding Frog, a high-stakes, physics-based platformer where every leap and grapple could be your last. Master the art of the swing as you painstakingly ascend through a treacherous world to reclaim your precious pudding from the cunning Harry the Heron. Do you have what it takes?' FROM games WHERE igdb_id = 334201 ON CONFLICT (game_id, language_code) DO NOTHING;
