INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aerial Raider', 'Embark on an exhilarating journey in Aerial Raider, a nostalgic top-down arcade shooter that combines classic 1980s pixel art with high resolution backgrounds and high-quality modern audio. Step into the cockpit as Commander Kael Riven and take to the skies in a relentless battle against the Varkari, an alien race from a dying sun. Your mission: shoot down waves of foes, navigate through intense aerial dogfights, and uncover a compelling story that will keep you on the edge of your seat.' FROM games WHERE igdb_id = 375730 ON CONFLICT (game_id, language_code) DO NOTHING;
