INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PlushiePet', 'Feeling overwhelmed? Tired of waking up to dystopian and/or exhausting news stories? Wish the world would slow down? Here at PlushiePet Corporation, we''ve got your back. PlushiePet is a wellness and utility companion with 100+ features, and dozens of adorable designs randomly distributed via blind boxes! Your PlushiePet is uniquely yours! And you are theirs. It''s an alarm clock. It''s a wellness app. It''s a 3D printer. It''s a geiger counter. And it''s the only friend you''ll ever need.' FROM games WHERE igdb_id = 383326 ON CONFLICT (game_id, language_code) DO NOTHING;
