INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goblin Gold Hunt', 'Play as a greedy little goblin with an oversized sack and an even bigger hunger for loot! Dash, jump, and snatch every coin, chest, and shiny treasure in sight as you chase your dream of becoming the richest goblin in the world. Fortune favors the bold—and the gold-hungry! But watch out! Taking damage or dying will make you lose coins! Try your best to reach the end with the maximum amount of coins and show to the world the your greediness know no bounds!' FROM games WHERE igdb_id = 379121 ON CONFLICT (game_id, language_code) DO NOTHING;
