INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nexen', 'A first-person horror action game set inside a shifting neon maze where the player must collect orbs, complete objectives, and survive. In NEXEN, you navigate dark corridors while being hunted by a relentless entity that reacts to sound and movement. Each mode changes the rules—Classic focuses on survival and orb collection, while Task Mode adds objectives and hazards. Blending retro visuals, industrial sound design, and high-intensity chases, the game challenges players to stay calm, adapt, and escape before the maze consumes them.' FROM games WHERE igdb_id = 375713 ON CONFLICT (game_id, language_code) DO NOTHING;
