INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Demon Kirsten', 'Our protagonist "Kirsten" is a soldier troubled by her current way of life.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 379205 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
