INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('150-floors', 228439, '2025-10-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ouf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar24po.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '150 Floors', '150 Floors of Magic or 150 Floors for short, is a tile-based, real-time strategy RPG where you play as a mage with either a Fire, Ice or Electric element, with more to come. Each mage has a wish they want granted or goal they want to meet. The only similarities they share is each mage wants to reach and conquer the 150th floor, granting them any wish they desire... Or so the saying goes. Beware, the floors made of tiles have a durability limit. If you attack a monster, you''re also attacking the tile as well and it may break, sending the monster one floor down. The same logic also applies to you. If you fall through, you drop to the previous floor. Defeat all monsters on a floor, and ascend to the next floor. How will you fare against the 150 Floors? Will you get your wish granted?' FROM games WHERE igdb_id = 228439 ON CONFLICT (game_id, language_code) DO NOTHING;
