INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ambulance Simulator 911 Rescue', 'Become the unsung hero in Ambulance Simulator 911 Rescue, an engaging game where you play the role of both an ambulance driver and a paramedic. Receive emergency calls in real-time and react quickly: turn on the sirens, drive at high speed through heavy traffic, provide first aid at the scene, and safely transport patients to the hospital.' FROM games WHERE igdb_id = 370560 ON CONFLICT (game_id, language_code) DO NOTHING;
