INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StackZap', 'StackZap is a game about stacking up differently colored balls in rows, columns and diagonals of 3 or more of the same color. You get points not for clearing them, but based on a distance that the remaining balls fall. There are 5 colors of the balls: red, green, blue, yellow, gray. The game is over when any of the balls is outside the play field.' FROM games WHERE igdb_id = 337983 ON CONFLICT (game_id, language_code) DO NOTHING;
