INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rage Tower', 'Rage Tower is a pixel-art platformer full of traps and frustration. You play as a small white character thrown to the top of a deadly tower. Your goal is to descend safely, navigating handcrafted traps, collapsing floors, and deceptive safe zones. The game blends cheerful visuals with punishing level design, offering a contrast between cute aesthetics and relentless difficulty. Expect emotional outbursts, broken keyboards, and the irresistible urge to try “just one more time”' FROM games WHERE igdb_id = 355033 ON CONFLICT (game_id, language_code) DO NOTHING;
