INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A House That Glows', 'A House That Glows is a choice-driven visual novel about a journalist who comes to help a forgotten village—and stumbles into a mystery that only appears at midnight. Stranded by a blizzard, Shon finds shelter with the kind Atcins family, hears whispers about an orphanage that burned long ago, and sees the impossible: a house shining on the hill where only ruins should be. Pulled between duty to his family and a promise to strangers, he follows the light and uncovers a story the world tried to bury.' FROM games WHERE igdb_id = 389593 ON CONFLICT (game_id, language_code) DO NOTHING;
