INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hula-hula-wee', 372290, '2025-10-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaska.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4m1l.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hula Hula Wee', 'Tropical puzzles, fruity explosions! In Hula Hula Wee, every level is a refreshing mix of logic and fun. Push coconuts across colorful maps, smash them into pineapple towers, and watch as they burst together into delicious Piña Coladas. The rules are simple, but the challenge keeps growing. Slide coconuts carefully, plan your moves, undo mistakes infinitely, and use bonfires to burn obstacles out of the way. To complete a stage, you’ll need to destroy every pineapple tower and outsmart each tricky layout. The adventure spans 30 puzzles across three vibrant settings. Start on CoCo Island, where the basics are introduced with lighthearted challenges. Then head to Hula Beach, where new twists like craters force coconuts to stop mid-path. Finally, climb the Fire Tower, the toughest destination, where bonfires add a fiery layer of strategy to your quest. With its tropical theme, playful mechanics, and clever progression, Hula Hula Wee is the perfect puzzle getaway for anyone who loves a mix of brains and beach vibes.' FROM games WHERE igdb_id = 372290 ON CONFLICT (game_id, language_code) DO NOTHING;
