INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Ilha Perdida da Babitonga', 'The project Babitonga: A Comic Adventure of the Mangrove Gang is an exciting digital comic in the visual novel style, taking readers on a journey to explore the rich biodiversity and culture of Babitonga Bay in Santa Catarina. With captivating characters like the Mangrove Gang, the game tells an adventure filled with mysteries, challenges, and discoveries about nature and the importance of preserving the environment.
