INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drive and Unwind', 'Drive And Unwind — Your Gentle Companion for Work and Study Drive And Unwind is a light and soothing tool featuring 2D parallax backgrounds, vehicle and weather options, five music genres, and a Pomodoro timer — perfect for relaxing during work or study.' FROM games WHERE igdb_id = 344107 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 344107 AND ge.slug = 'indie' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 344107 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
